import secrets
import unittest

from csrf import token_for


class ResubmitKeepsToken(unittest.TestCase):
    def test_resubmit_carries_the_sessions_token(self):
        seeded = secrets.token_hex(8)
        session = {"csrf": seeded}
        self.assertEqual(token_for(session), seeded)
        self.assertEqual(session["csrf"], seeded)

    def test_first_submit_mints_one_token_and_reuses_it(self):
        session = {}
        first = token_for(session)
        self.assertIsInstance(first, str)
        self.assertTrue(first)
        self.assertEqual(token_for(session), first)
        self.assertNotEqual(token_for({}), first)


if __name__ == "__main__":
    unittest.main()
